private sealed class RebuildJob : IApiJob
{
    public string Kind => "rebuild";
    public string? Perm => "jobs.rebuild";
    public IReadOnlyList<string> Phases => ["Read", "Write"];

    public Task<OSResult<object>> PlanAsync(CancellationToken token) =>
        Task.FromResult(OSResult<object>.Ok(new { rows = 3 }));

    public Task<OSResult<object>> RunAsync(JobProgress progress, CancellationToken token)
    {
        progress.Phase(0, 3);

        for (var i = 0; i < 3; i++)
        {
            token.ThrowIfCancellationRequested();
            progress.Advance();
        }

        progress.Phase(1, 1);
        progress.Note("writing");
        progress.Advance();

        return Task.FromResult(OSResult<object>.Ok(new { rows = 3 }));
    }
}

