var folder = Path.Combine(Path.GetTempPath(), $"lorea-keys-{Guid.NewGuid():N}");

try
{
    var provider = new Microsoft.AspNetCore.DataProtection.EphemeralDataProtectionProvider();
    var first = new DataProtectionKeyRing(provider, folder);
    var id = first.CurrentKeyId;
    var reopened = new DataProtectionKeyRing(provider, folder);

    return [$"key id has {id.Length} characters", $"same key after reopening: {reopened.CurrentKeyId == id}", $"files on disk: {Directory.GetFiles(folder).Length}"];
}
finally
{
    if (Directory.Exists(folder))
        Directory.Delete(folder, recursive: true);
}
